"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

REQUEST_TIMEOUT_SECONDS = 5
MAX_RETRIES = 3
BACKOFF_BASE_SECONDS = 1


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclass
class DeliveryAttempt:
    """The outcome of a single delivery attempt."""

    status: int | None
    error: str | None


@dataclass
class DeliveryResult:
    """The outcome of a delivery, including every attempt made."""

    success: bool
    status: int | None
    attempts: list[DeliveryAttempt] = field(default_factory=list)


def deliver(url: str, payload: dict, sleep=time.sleep) -> DeliveryResult:
    """POST a payload to a subscriber endpoint, retrying retryable failures.

    Each request has a 5 second timeout. A 5xx response or a connection error is retried up to
    MAX_RETRIES times with exponential backoff; a 4xx response is treated as final.
    """
    body = json.dumps(payload).encode()
    attempts: list[DeliveryAttempt] = []
    for attempt_number in range(1, MAX_RETRIES + 2):
        request = urllib.request.Request(url, data=body, method="POST")
        request.add_header("X-Signature", sign(json.dumps(payload)))
        logger.info("delivering %s to %s, attempt %d", new_delivery_id(), url, attempt_number)
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                attempts.append(DeliveryAttempt(status=response.status, error=None))
                return DeliveryResult(success=True, status=response.status, attempts=attempts)
        except urllib.error.HTTPError as exc:
            attempts.append(DeliveryAttempt(status=exc.code, error=str(exc)))
            if exc.code < 500:
                return DeliveryResult(success=False, status=exc.code, attempts=attempts)
        except urllib.error.URLError as exc:
            attempts.append(DeliveryAttempt(status=None, error=str(exc.reason)))
        if attempt_number <= MAX_RETRIES:
            sleep(BACKOFF_BASE_SECONDS * 2 ** (attempt_number - 1))
    return DeliveryResult(success=False, status=attempts[-1].status, attempts=attempts)

